	@Test
	void pageEstimateRejectsEmptyUnknownAndInvalidInputsAndNeverUsesAFractionalBuffer() {
		assertThat(LmdbNativeParallelKernelRows.expectedOutputPageRows(0D, 0L, 2)).isZero();
		assertThat(LmdbNativeParallelKernelRows.expectedOutputPageRows(16D, 0L, 2)).isZero();
		assertThat(LmdbNativeParallelKernelRows.expectedOutputPageRows(Double.NaN, 16L, 2)).isZero();
		assertThat(LmdbNativeParallelKernelRows.expectedOutputPageRows(Double.POSITIVE_INFINITY, 16L, 2)).isZero();
		assertThat(LmdbNativeParallelKernelRows.expectedOutputPageRows(-1D, 16L, 2)).isZero();
		assertThat(LmdbNativeParallelKernelRows.expectedOutputPageRows(16D, -1L, 2)).isZero();
		assertThat(LmdbNativeParallelKernelRows.expectedOutputPageRows(16D, 16L, 1)).isZero();
		assertThat(LmdbNativeParallelKernelRows.expectedOutputPageRows(16D, 16L, 0)).isZero();
		assertThat(LmdbNativeParallelKernelRows.expectedOutputPageRows(0.25D, 16L, 2)).isEqualTo(1);
		assertThat(LmdbNativeParallelKernelRows.expectedOutputPageRows(16D, 16L, 2)).isEqualTo(2);
		assertThat(LmdbNativeParallelKernelRows.expectedOutputPageRows(512D, 512L, 2)).isEqualTo(64);
		assertThat(LmdbNativeParallelKernelRows.expectedOutputPageRows(2_048D, 2_048L, 2)).isEqualTo(256);
		assertThat(LmdbNativeParallelKernelRows.expectedOutputPageRows(Double.MAX_VALUE, Long.MAX_VALUE,
				Integer.MAX_VALUE)).isEqualTo(256);
	}

